private Map<String, BigDecimal> calcularAjustePagamento(BigDecimal total, String forma, int parcelas) {
    Map<String, BigDecimal> resultado = new HashMap<>();
    BigDecimal ajuste = BigDecimal.ZERO;

    if (forma.equals("PIX")) {
        BigDecimal desconto = total.multiply(new BigDecimal("0.05"));
        ajuste = arredondar(desconto.negate());
    } else if (forma.equals("BOLETO")) {
        ajuste = arredondar(new BigDecimal("3.49"));
    } else if (forma.equals("CARTAO") && parcelas > 3) {
        BigDecimal taxaMensal = new BigDecimal("0.0199");
        BigDecimal fator = BigDecimal.ONE.add(taxaMensal).pow(parcelas).negate();
        BigDecimal denominador = BigDecimal.ONE.subtract(fator);
        BigDecimal taxa = taxaMensal.divide(denominador, 10, RoundingMode.HALF_EVEN);

        BigDecimal valorComJuros = total.multiply(taxa.multiply(new BigDecimal(parcelas)));
        ajuste = arredondar(valorComJuros.subtract(total));
    }

    resultado.put("ajuste", ajuste);
    return resultado;
}

