        request.setModalidadeEntrega("ECONOMICA");
        request.setCupom(null);
        request.setFormaPagamento("CARTAO");
        request.setParcelas(6);

        CheckoutResponse response = service.calcularResumo(request);

        assertEquals(0, new BigDecimal("409.70").compareTo(response.getSubtotalProdutos()));
        assertEquals(0, new BigDecimal("0.00").compareTo(response.getDescontoCupom()));
        assertEquals(0, new BigDecimal("15.60").compareTo(response.getFrete()));
        assertEquals(7, response.getPrazoEntregaDias());
        assertEquals(6, response.getParcelas());
        assertTrue(response.getTotalFinal().compareTo(new BigDecimal("425.30")) > 0);
        assertTrue(response.getValorParcela().compareTo(BigDecimal.ZERO) > 0);
        assertEquals(0, response.getValorParcela().multiply(new BigDecimal("6")).compareTo(response.getTotalFinal()));
    }

