        assertTrue(response.getFrete().setScale(2, RoundingMode.UNNECESSARY).compareTo(new BigDecimal("15.60")) == 0);
        assertEquals(7, response.getPrazoEntregaDias());
        assertEquals(6, response.getParcelas());
        assertTrue(response.getTotalFinal().compareTo(new BigDecimal("425.30")) > 0);
        assertTrue(response.getValorParcela().compareTo(BigDecimal.ZERO) > 0);
